import sys,json
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT,read_csv
by={r['question_id']:r for r in read_csv('data/questions.csv')}
initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_029_independent_answers.json').read_text())['questions']}
items=[]
def add(q,summary,values,reasons,solution,concept,labels,knowledge,ambiguity='',discipline='geo_sediment',direction='最も不適切・誤りを選ぶ',difficulty=3,cites=None):
 r=by[q];a=int(initial[q]['independent_answer']);assert len(values)==len(reasons)==5
 positive=q in ['R01-REG-APPLIED-28','R06-REG-APPLIED-30','R02-REG-APPLIED-31']
 items.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=summary,summary=summary,
 conditions={'判断方向':direction,'原典照合':'15原典画像で18問の問題幹、全5肢、否定、専門語、化学式、候補順を確認。','適用条件':'流れと構造の典型対応は一意成因を保証しない。用語、時間間隙、保存、試料処理の条件を個別に示す。'},
 choices={str(i):dict(value=v,verdict=('該当・適切' if i==a else '非該当・不適切') if positive else ('誤り・最も不適切' if i==a else '適切（条件を含めて検討）'),reason=w) for i,(v,w) in enumerate(zip(values,reasons),1)},
 figures='設問固有の図なし。全候補・専門語・化学式を原典で照合。',ambiguity=ambiguity,
 evidence=['extracted/pages/'+r['source_year_directory']+'/17_applied_science/page_'+str(p).zfill(3)+'.png' for p in range(int(r['source_page']),int(r['source_page_end'])+1)],
 core_concept=summary,required_knowledge=knowledge,solution=solution,answer_reason=solution,
 independent_answer=initial[q]['independent_answer'],independent_solution_note='公式参照前に15原典画像から18初回解答を保存。'+initial[q]['reason']+'全18問の公式との一致を確認。初回記録は改変しない。',
 learning_points='観察できる構造と成因・環境の解釈を区別する。代表モデルに適用条件を添え、単一の形や測定値から唯一の環境を断定しない。',
 theory_references=labels,discipline_id=discipline,concept_id=concept,cross_concepts=[],
 classification_reason='18問の原典内容を確認。構造・堆積環境はgeo_sediment、時間対比はgeo_stratigraphy、岩種形成の比較H24問29はgeo_petrology、火砕流R01問25はearth_volcanoへ割り当てる。旧分類と変更理由を出版記録に保持。',
 calculation='false',figure='false',law='false',
 evaluation=dict(knowledge_novelty='3',reasoning_steps='2',calculation_load='0',figure_reading='0',difficulty=str(difficulty),difficulty_reason='対象読者には流体と粒子の物理は既知だが、地質用語・観測と逆推定・原典の全称表現の範囲を新たに学ぶ必要がある。地質分野としてAstra査読を要する。'),
 citations=cites if cites is not None else ['sed_mit_environment'],foundationality='high',transferability='high'))

facies_values=['河川を蛇行・網状の二端成分で考える','海湖側へ突出するデルタを海退期のシステムとする','海進で河口が沈水する内湾をエスチュアリーとする','氾濫原の砂岩に見られる逆級化を河川の特徴とする','蛇行河川を流量変動・勾配・粗粒負荷の大きい河川とする']
facies_reasons=['端成分モデルとして妥当である。中間形態や両特徴を持つ河川を除外する絶対二分ではない。','デルタの前進が海退を示す場合の説明である。海退を海水準低下と同義にせず、デルタの存在だけで全時期を決めない。','沈水谷を河川と潮汐が埋める河口内湾というモデルに対応する。海進する全河口の唯一の形ではない。','洪水の増水過程では砂が上方粗粒化する場合がある。ただし逆級化は河川に固有ではなく、全氾濫原砂がそうなるという意味ではない。','これは網状河川の典型条件との混同である。蛇行は流路の曲率と側方移動、ポイントバーと泥質氾濫原で捉える。']
facies_solution='五つは河川の端成分と河口堆積システムの対応を問う。蛇行の典型を、急勾配・大きな流量変動・粗粒子の大きな負荷で説明する肢を除く。この組合せは網状の典型に対応する。ただし実際の流路型には河岸の強度や供給も関わる。デルタは前進する堆積体で、海退と相対海水準低下は同義ではない。逆級化も洪水立上がりで形成し得るが、非一意の指標である。原典の典型モデルと、全称命題としての限界を分けて解く。'
facies_ambiguity='デルタを海退期と呼ぶ範囲、氾濫原砂の逆級化の代表性は要限定である。逆級化は他成因にもあり河川に一意ではない。全河川・全デルタの排他的な診断とはしない。独立初回と公式の蛇行/網状混同肢を保持する。'
for q,order in [('H23-REG-APPLIED-25',[0,1,2,3,4]),('H29-REG-APPLIED-25',[0,1,2,3,4]),('R05-REG-APPLIED-30',[0,3,4,1,2])]:
 add(q,'河川と河口の堆積システムを比較し、蛇行と網状の典型条件を区別する。',[facies_values[i] for i in order],[facies_reasons[i] for i in order],facies_solution+'本問の該当番号は'+initial[q]['independent_answer']+'である。','sed_facies_system',['theory:sediment:river','theory:sediment:grading','theory:sediment:delta'],'河川端成分、氾濫原とポイントバー、洪水時の級化、デルタ前進、相対海水準と供給、河口沈水。',ambiguity=facies_ambiguity,cites=['sed_mit_environment','sed_walther_oregon'])

add('H23-REG-APPLIED-35','堆積環境を反映する地球化学的指標と、元素分析・粒子表面観察の測定対象を分ける。',
 ['FeS2含有量は堆積環境に依存する','自然水の陰イオン量は淡水より海水が多い','XRFで内部の堆積構造を観察する','石英表面のSEMは風成作用の推定に有効','粘土混濁水の電気伝導度変化は古環境に対応する'],
 ['硫化物形成は硫黄・鉄の供給、還元状態などに依存する。酸化・溶脱後の値を堆積時と無条件に同一視しない。','通常の海水は塩化物等の溶存イオン濃度が淡水より大きい。塩湖等の例外を含む全ての水への全称ではない。','蛍光X線のエネルギーと強度から元素を分析するので、内部堆積構造の画像を直接得る方法ではない。','粒子表面の微細摩耗・衝突形態を環境推定に使える。ただし水成・風成・溶食や再運搬の履歴を単独で一意決定しない。','懸濁液のECを古環境指標とする研究があるが、乾燥と酸化、混合比や温度、後の溶脱にも依存し、単独判定の限界がある。'],
 r'蛍光X線分析は試料の原子を励起し、その特性X線を使う元素分析である。内部の葉理や粒子配列を観察する方法という3が誤りである。黄鉄鉱 \(\mathrm{FeS_2}\) は環境に応じて生成・酸化し、粘土の懸濁液のECもその反応に関わる。GSJの2011年資料は試料処理によるECの変化と環境推定の限界を示す。SEMの表面観察では風による運搬を推定する証拠を得られるが、後の化学的改変も検討する。',
 'sed_proxy_methods',['theory:sediment:proxy'],'XRFの特性X線と元素量、SEMの表面観察、硫化物と酸化還元、ECの試料処理依存。',ambiguity='陰イオン量の典型比較とECの古環境対応は濃度・試料処理・後の履歴に依存する。SEMの原典用語に対応する手法全体の追試は未確認。一次資料で確認した範囲と限界を明記して部分校正に残す。',cites=['sed_xrf_jaea','sed_gsj_ec2011','sed_sem_shimane'])

add('H24-REG-APPLIED-29','堆積岩名と、堆積原岩を変成した岩石、剪断変形で分類する岩石の関係を比較する。',
 ['ドロマイト（苦灰岩）','石灰岩','マイロナイト','チャート','粘板岩'],
 ['本問は鉱物名でなく括弧で苦灰岩という岩石を指定する。炭酸塩堆積岩に関係する。','炭酸カルシウム主体の岩石で、生物・化学的堆積やその後の変化を考える。','強い剪断変形と動的再結晶などで生じる変形岩の分類であり、特定の堆積成因を表す名ではない。','シリカに富む堆積岩で、珪質生物殻の集積などが代表となる。','泥質堆積原岩の低度変成と劈開に関わる。GSJにも堆積岩区分の登米粘板岩の標本があり、堆積岩との関係を切れない。'],
 '本問の方向は「堆積岩でないもの」ではなく「最も関係のないもの」である。ドロマイトは苦灰岩と明示され、石灰岩とチャートも堆積に関連する。粘板岩は泥質堆積原岩の変成として関係を持つ。一方、マイロナイトは原岩の種類より剪断変形に基づく名称なので3を選ぶ。ただし堆積原岩からマイロナイトができる場合もあり、関係が絶対にゼロという解釈にはしない。',
 'concept_051',['theory:petrology:cycle','theory:petrology:metamorphism','theory:petrology:deposition'],'鉱物名と岩石名、炭酸塩と珪質堆積、泥質原岩と変成、剪断変形による分類。',ambiguity='粘板岩は通常は低度変成岩に分類されるが、堆積原岩との関係がある。マイロナイトにも堆積原岩の例を排除できず「最も関係ない」という相対判断の範囲をAstraへ残す。',discipline='geo_petrology',direction='堆積岩に最も関係のない名称を選ぶ',cites=['sed_gsj_slate'])

add('H28-REG-APPLIED-34','地層対比で使う微化石・花粉・火山灰・古地磁気の情報と適用域を比較する。',
 ['海成層の広い分布を鍵層として使う','微化石を堆積環境調査に使う','花粉は淡水成層のみに含まれる','同一火山灰層を最も確かな対比の決め手とする','古地磁気は定方位試料で調べる'],
 ['広く追跡できる特徴的な海成層は鍵となることがある。ただし海成であるだけで同時面とはならない。','珪藻、有孔虫、放散虫、貝形虫などの組成が生息域や堆積環境の材料となる。再堆積も考慮する。','海成層でも花粉化石が記録され、陸上植生の変遷や対比に使われる。「のみ」という限定が誤りである。','同一噴火の初生テフラを正しく同定すれば強い時間対比となる。一律にどの手法より確かとはせず、再堆積と誤対比を除く。','磁化方向を地理方向へ対応させる必要があるため方位を保持する。傾動や再磁化の補正も別に必要である。'],
 '花粉は陸上で作られても風や河川によって海へ運ばれる。海成層の花粉分析による層序対比が実際に報告されているため、淡水成層だけとする3が最も不適切である。微化石と古地磁気は別の観測量を持ち、火山灰は一回の噴火を同定できる場合の対比に強い。広い海成層や火山灰の利点を、全条件での同時性・最確性へ広げない。',
 'strat_tephra_correlation',['theory:stratigraphy:marker','theory:stratigraphy:pollen','theory:stratigraphy:scope'],'花粉の運搬・海成保存、微化石群集、鍵層と時間面、初生テフラ、定方位試料。',ambiguity='海成層が常に鍵層、火山灰が常に一番確かという強い一般化は成立範囲を要する。花粉の淡水限定の誤りは確認済みだが、他肢の代表性を部分校正で追跡する。',discipline='geo_stratigraphy',cites=['strat_pollen_tokushima','strat_gsj_atsumi'])

structure_values=['床形の移動で前面へ層が付き斜交層理となる','蛇行河川の代表としてヘリンボーンを挙げる','暴浪の波浪でハンモック状斜交層理が形成する','混濁流がタービダイトを作り一般に級化する','流れの小さな削込みを流痕とする']
structure_reasons=['移動する床形の下流側斜面への堆積が内部の斜交を保存するという説明に対応する。','相反する流向で傾斜の異なる層が重なる構造は潮流を典型とし、蛇行の一方向流の主な構造という対応が違う。','ストームの振動流・複合流が代表的な形成条件である。形の名称から全例の単一成因を断定しない。','密度差で流れ、乱流が粒子を支持し、流れの減衰と沈降で級化しやすい。全例で全Bouma区分がそろうとは限らない。','流れが底面を侵食した痕跡であり、充填された型が上位層底面に保存される場合もある。']
for q,order in [('H30-REG-APPLIED-25',[0,1,2,3,4]),('R04-REG-APPLIED-28',[1,2,0,4,3]),('R07-REG-APPLIED-27',[4,0,1,3,2])]:
 values=[structure_values[i] for i in order];reasons=[structure_reasons[i] for i in order]
 ambiguity=''
 if q=='H30-REG-APPLIED-25':
  values[3]='陸棚斜面の海底地すべりに起源を持つ混濁流の堆積物がタービダイトで級化・Boumaが特徴'
  reasons[3]='海底地すべりは混濁流の発生源の一つである。級化とBoumaは典型だが全ての混濁流の起源や全区分の存在を限定する定義ではない。'
  ambiguity='海底地すべりを全タービダイトの起源、全Bouma区分を必須とする読みは過度である。HCSにも多成因がある。公式/独立2を保持して典型対応の範囲を部分校正に残す。'
 add(q,'流れ・波浪と堆積構造を対応させ、蛇行河川と往復する潮流の構造を区別する。',values,reasons,
 '床形の前進は斜交層理を保存し、流れの侵食は流痕を作る。混濁流の減衰は一般に級化したタービダイトを残す。ハンモック状斜交層理では暴浪時の振動流又は複合流が代表となる。ヘリンボーンを蛇行河川の主な構造に割り当てる対応が最も不適切であり、本問の番号は'+initial[q]['independent_answer']+'である。潮流の反転を典型とするが、一断面の逆傾斜だけで真の180度反転を断定しない。原典のタービダイト説明も全例の起源を限定せず読む。',
 'sed_bedform_flow',['theory:sediment:cross','theory:sediment:herringbone','theory:sediment:hcs','theory:sediment:turbidite'],'床形の移動と斜交、往復流、振動・複合流、密度流、流痕、典型成因の適用条件。',ambiguity=ambiguity,cites=['sed_mit_environment','sed_mit_cross','sed_houston_structures'])

add('R01-REG-APPLIED-25','火砕流の発生・混合物・堆積性状と、地形を反映する分布を比較する。',
 ['一般に分級が悪く塊状となる','大規模火砕流は高発泡のプリニー式に伴い通常カルデラを作る','高温火砕物・火山ガス・取り込む大気が地面に沿って流れる','ドームの爆発型をプレー型、重力崩落型をメラピ型とする','分布は火口を長軸の一端に持つ単純な長円が多い'],
 ['多粒径を混合して急速に堆積する流れの代表的特徴である。希薄サージ等の全堆積物へ塊状を強制しない。','高発泡マグマの大規模噴出とカルデラ形成の典型を述べるが、全活動様式の必要十分条件としては確認していない。','高温粒子と気体の混合物が地形に沿って流下する現象に対応する。固体だけ又は溶岩だけではない。','メラピのドーム崩落起源は一次論文で確認した。プレー型という原典呼称と全類型の整理は追加確認を要する。','谷沿いの舌状・ローブ状、複数谷の埋積などを取り得る。風で伸びる降下物の模式分布と混同する一般化である。'],
 '火砕流は地面に沿う密度流で、経路と堆積域は谷や尾根、流れの濃度に依存する。USGSには重なった扇状・舌状・ローブ状の分布及びメラピの谷埋積と希薄サージ分離の報告がある。従って単純な長円形が一般的だとする5が最も不適切である。降下火山灰は風に運ばれるため別の分布モデルを使う。大規模噴出・カルデラやプレー型という呼称は、この資料確認だけで全例を普遍化せず原典の典型説明として保持する。',
 'volc_pyroclastic_distribution',['theory:volcanology:pyroflow','theory:volcanology:source','theory:volcanology:distribution'],'火砕密度流の粒子と気体、ドーム崩落、噴煙柱、地形と分布、降下と流下の区別。',ambiguity='大規模火砕流/プリニー/カルデラの一般化とプレー型の用語範囲は全類型の一次資料照合が未完了である。公式/独立5と確認済みの非単純分布を保持し部分校正に残す。',discipline='earth_volcano',cites=['volc_usgs_merapi','volc_usgs_msh_flow'])

soft_names=['流痕','火炎構造','リップル','葉理','級化層理']
soft_reasons=['流れが堆積面を侵食する初生構造である。','砂泥の荷重差や流動化による、堆積後の未固結変形の二次構造である。','堆積しながら流れが床形を作る初生構造である。','堆積粒子の層状配列を記録する初生構造である。後から変形した葉理という別概念と区別する。','堆積中の粒径の時間変化を記録する初生構造である。']
for q,order in [('R01-REG-APPLIED-28',[0,1,2,3,4]),('R06-REG-APPLIED-30',[3,4,1,2,0])]:
 add(q,'堆積中にできる構造と、その後の未固結段階に変形してできる構造を区別する。',[soft_names[i] for i in order],[soft_reasons[i] for i in order],
 '分類の軸は形の大きさではなく形成時期と過程である。流痕・リップル・葉理・級化は流れと沈積による初生構造に対応する。火炎構造は未固結の泥が上の砂へ突き出す荷重・流動化に関わるため二次構造であり、本問では'+initial[q]['independent_answer']+'である。後から曲げられた葉理を見た場合は、葉理の形成と変形を別の段階として読む。火炎があるだけで地震と断定しない。',
 'sed_soft_deformation',['theory:sediment:soft','theory:sediment:cross','theory:sediment:grading'],'初生/二次の分類軸、未固結変形、荷重差・間隙水、葉理と後の変形の区別。',direction='堆積後の未固結段階の二次構造を選ぶ',cites=['sed_soft_deformation','sed_houston_structures'])

add('R02-REG-APPLIED-29','転倒した地層の形成時の上下を決める構造と、節理の伝播を示す構造を区別する。',
 ['羽毛状構造','皿状構造','荷重痕','流痕','生痕化石'],
 ['節理の破断面の起点から広がる伝播模様である。堆積時の上下面を直接示さない。','一般に上に凹の脱水構造の形と周囲の層を使い上下を検討できる。','上の砂が下の泥へ突出するため、荷重の向きを使える。','侵食した凹面と上位層底面の凸型の充填を区別すると上下を検討できる。','巣穴の開口・分岐や地表からの貫入などが明瞭なら上下を使える。全ての名称だけで上下が分かるとは限らない。'],
 '羽毛状構造は固結岩の割れ目が広がった過程を記録する。堆積時の上を示す幾何ではないため1が最も不適切である。皿状・荷重・流痕は形成時の重力や層の界面との対応から上下を考え、生痕は開口や埋積を含めて読む。現在の鉛直と堆積時の鉛直は転倒で違うため、一つの曖昧な形だけでなく複数構造を合わせる。',
 'sed_way_up',['theory:sediment:wayup','theory:sediment:soft'],'節理と堆積構造、脱水皿の幾何、荷重方向、侵食型と底面型、生痕の開口。',cites=['sed_plumose_michigan','sed_mit_environment','sed_houston_structures'])

add('R02-REG-APPLIED-31','火山砕屑物を使う地層対比の適用範囲と、野外記載・鉱物分析の役割を比較する。',
 ['局地的テフラを避け広域テフラだけを使う','陸上地層だけに適用する','色・粒度・層厚を使わず屈折率と組成で同定する','テフラは一般に火山砕屑物で溶岩と区別する','後期更新世以降だけに適用する'],
 ['局地的噴火層もその地域の時間対比に使える。広域性は用途の利点であり必須条件ではない。','海や湖の堆積物中のテフラも時間対比に使える。','分析値は重要だが野外の層序位置・色・粒径・層厚も使う。GSJの対比訂正には粒径/層厚による候補排除がある。','破片状の噴出物を連続した溶岩流と分けるという本問の一般的な用語に対応する。','GSJの中期更新世海成層の対比例だけでもこの限定への反例になる。古い層では保存と変質を別途検討する。'],
 'テフラは火山の破片状噴出物を扱うので溶岩と区別する4が適切である。他は有効な材料を不当に除外する。局地層も局地対比に使え、海成・湖成層も対象となり、中期更新世の対比例がある。同定は野外の形質とガラス/鉱物分析を併用する。テフラの狭義・広義が文献で違うこと、初生と再堆積が年代解釈を変えることは別の確認事項である。',
 'strat_tephra_correlation',['theory:stratigraphy:tephra','theory:stratigraphy:identify','theory:stratigraphy:scope'],'破片状火山物質、局地/広域の用途、海湖成保存、中期更新世対比例、野外・分析の併用。',discipline='geo_stratigraphy',direction='最も適切な記述を選ぶ',cites=['volc_usgs_tephra','strat_gsj_tephra2013','strat_gsj_atsumi'])

add('R03-REG-APPLIED-30','津波堆積物を、供給源、反復する流れ、非地震起源と形成後の保存条件から検討する。',
 ['生物遺骸から侵食した海底の深度を検討する','堆積構造は比較的単純な場合が多い','礫床河川・扇状地・岩礁海岸は調査に不向き','火山・隕石・海底地すべり起源の津波にも報告がある','内湾は安定した環境で保存されやすい'],
 ['生物の生息深度は供給源を制約する証拠となるが、混合と再堆積の影響を考慮する。','多様な層理・正逆級化・複数波のユニットがあるため一律な単純化が問題となる。ただしUSGS近年資料では構造が稀な例も多く、単純/複雑の一般頻度は資料依存である。','通常の粗粒供給や侵食でイベント層の識別・保存が難しい。岩礁に津波記録が絶対にないという意味ではない。','隕石衝突とストレッガーの報告は確認した。火山起源堆積物の個別報告は今回未確認であり断定的な全確認扱いにしない。','静かな内湾・湿地の背景堆積と後の埋積は保存に有利な場合がある。侵食や擾乱を受けない保証ではない。'],
 '初回は波の反復・戻り流れによる多様性から2を最も不適切と判定し、公式2に一致した。藤野の報告は塊状から複数級化ユニットまでの多様性を示す。一方、USGSの近年の事例集では堆積構造が稀な例も多い。したがって「津波なら必ず複雑だから2が誤り」とは書けず、対象環境・記録の尺度による頻度の違いを疑義に残す。生物遺骸、分布、構造、年代などの複数証拠で認定し、形成と保存と観察可能性を分ける。',
 'sed_tsunami_record',['theory:sediment:tsunami'],'反復波と遡上/戻り流れ、供給源、微化石、背景堆積と保存、非地震起源、事例頻度の母集団。',ambiguity='公式/独立2を保持するが、単純/複雑の頻度は環境と尺度に依存し、USGSには構造が稀な例も多い。②の代表頻度を厳密には未確定。④の火山起源津波堆積物の個別報告も未確認。①③⑤の一般化の限界を含めAstra重点査読へ残す。',difficulty=4,cites=['sed_tsunami_fujino','sed_tsunami_usgs','sed_tsunami_2002','sed_tsunami_gsj_survey'])

add('R05-REG-APPLIED-31','一方向流で形成し得る層理と、波浪の振動・複合流が典型となる構造を比較する。',
 ['トラフ型斜交層理','ハンモック状斜交層理','フォーセット層理','平行層理','平板型斜交層理'],
 ['三次元の床形の移動・侵食と堆積により一方向流で形成し得る。','典型は暴浪の振動・複合流であり、本問で一方向流の代表として最も不適切である。ただし広義のHCSには複数成因が報告される。','床形の下流側斜面への堆積などにより一方向流で形成し得る。','床面に沿うシート状の運搬・堆積などで形成し得る。一方向流だけの固有指標という意味ではない。','二次元に近い床形の移動により一方向流で形成し得る。'],
 '四つは一方向の掃流や床形の移動で形成し得るのに対し、ハンモック状斜交層理は波浪の振動流・複合流の代表なので2を選ぶ。ただしMITは広義のHCSに反砂堆を伴う例を含む多成因を挙げる。「最も不適切」という試験の代表比較を、全ての一方向流条件で絶対に形成されないという証明へ置き換えない。',
 'sed_bedform_flow',['theory:sediment:cross','theory:sediment:hcs'],'一方向の床形と層理、振動流と複合流、形の分類と成因の非一意性。',ambiguity='広義のHCSには多成因があり、一方向流で絶対に不可能という全称は未支持である。初回/公式2は典型モデルの比較として保持し、用語範囲をAstraへ残す。',cites=['sed_mit_cross','sed_houston_structures'])

add('R06-REG-APPLIED-31','堆積相の記載、組合せ、累重の名前と、漸移的な上下関係の法則を区別する。',
 ['物理・生物・化学の特徴から堆積環境を復元する','側方隣接する環境の堆積物だけが漸移的に重なる','岩相・粒径・構造・化石で堆積相を区別する','堆積相の組合せを堆積シーケンスと呼ぶ','累重・配列を堆積相サクセションと呼ぶ'],
 ['観察記載から成因・環境を推定する解析の説明である。単一指標からの唯一解とはしない。','ワルターの法則の骨子である。原典の漸移的という条件を保持し、不整合を挟む全上下接触へ広げない。','相を区別する記載属性の組合せに対応する。環境の解釈と区別する。','組合せの名称は堆積相アソシエーションである。シーケンスは境界で区分する成因的な地層群であり同じではない。','相の上下の累重・配列というサクセションの説明に対応する。'],
 '堆積相を観察上の特徴で分け、組合せをアソシエーション、累重の順序をサクセションと呼ぶ。4は組合せをシーケンスとする用語の混同である。シーケンスは不整合又は対応する整合面で境界を定める地層群であり、単なる相の集合より条件が多い。ワルターの法則は漸移的・整合的な累重を扱うため、原典の条件を消して任意の上下接触へ使わない。',
 'sed_facies_walther',['theory:sediment:facies','theory:sediment:walther'],'観察属性と堆積相、association/succession、シーケンス境界、Waltherの連続・漸移条件。',cites=['sed_mit_environment','sed_walther_oregon'])

add('R07-REG-APPLIED-28','地層境界の時間間隙と、基盤岩種・層理の幾何による不整合の分類を比較する。',
 ['不整合面は多くの場合下位層の堆積直後の地形面','層状岩が非層状火成・変成岩を覆う不整合を無整合とする','平行な上下層で下位が顕著に削剥される境界を平行不整合とする','上下層の走向・傾斜が違う不整合を傾斜不整合とする','境界に時間間隙がほぼない関係を整合とする'],
 ['下位堆積後の非堆積、傾動や侵食を経て上位がたまるため、下位の堆積直後の面とは限らない。','堆積層が火成・変成基盤を不整合に覆う関係に対応する。','層理の平行性は時間的連続を保証しない。侵食と時間間隙がある平行不整合である。','下位が傾動・侵食された後に上位が堆積する幾何に対応する。','本問の層序関係の定義である。検出できない短い休止までゼロと断定する意味ではない。'],
 '不整合面を挟む間に記録されない時間と侵食がある。下位層の堆積後、固結・傾動・侵食が起きてから上位層が堆積することもあるため、下位の堆積直後の地形とする1が最も不適切である。無整合は基盤の火成・変成岩との関係、平行と傾斜不整合は上下層理の幾何で分ける。平行であるだけで整合とする判断を避ける。',
 'strat_unconformity',['theory:stratigraphy:hiatus','theory:stratigraphy:unconformity'],'層序の時間間隙、侵食と非堆積、傾動、基盤岩種、層理の走向・傾斜。',discipline='geo_stratigraphy',cites=['strat_iu_unconformity'])

